package com.worklyn.modules.leave.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.*;
@Document(collection="leave_requests")
public class LeaveRequest {
 @Id private String id; @Indexed private String employeeId; private LeaveType leaveType; private LocalDate startDate; private LocalDate endDate; private Integer totalDays; private String reason; private LeaveStatus status; private String approverId; private String decisionRemarks; private Instant decisionDate; private String workflowId; private Instant createdAt;
 public String getId(){return id;} public void setId(String v){id=v;} public String getEmployeeId(){return employeeId;} public void setEmployeeId(String v){employeeId=v;} public LeaveType getLeaveType(){return leaveType;} public void setLeaveType(LeaveType v){leaveType=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public Integer getTotalDays(){return totalDays;} public void setTotalDays(Integer v){totalDays=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public LeaveStatus getStatus(){return status;} public void setStatus(LeaveStatus v){status=v;} public String getApproverId(){return approverId;} public void setApproverId(String v){approverId=v;} public String getDecisionRemarks(){return decisionRemarks;} public void setDecisionRemarks(String v){decisionRemarks=v;} public Instant getDecisionDate(){return decisionDate;} public void setDecisionDate(Instant v){decisionDate=v;} public String getWorkflowId(){return workflowId;} public void setWorkflowId(String v){workflowId=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;}
}
